      const hpPct = hp.最大值 ? Math.min(100, (hp.当前值 / hp.最大值) * 100) : 0;
      const mpPct = mp.最大值 ? Math.min(100, (mp.当前值 / mp.最大值) * 100) : 0;
      const expPct = exp.升级所需值 ? Math.min(100, (exp.当前值 / exp.升级所需值) * 100) : 0;

      html += `
