            <span class="bar-text">${hp.当前值 || 0}/${hp.最大值 || 0}</span>
          </div>
          <div class="bar-row">
            <span class="bar-icon">💧</span>
            <div class="bar-track"><div class="bar-fill fill-mp" style="width:${mpPct}%"></div></div>
            <span class="bar-text">${mp.当前值 || 0}/${mp.最大值 || 0}</span>
